#!/usr/bin/env node
// Validates config/ and bundles it into build/config.js for the Cloudflare
// Worker, which can't read files at runtime. Runs automatically on
// `wrangler deploy` and `wrangler dev` (see "build" in wrangler.jsonc).
// A broken calculator file fails the build, so it can't be deployed.
import { mkdir, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { loadConfig, readConfigDir } from '../src/config-loader.js';
import { configDir } from '../src/runtime.js';

const OUT = fileURLToPath(new URL('../build/config.js', import.meta.url));

const dir = configDir();
try {
  const config = await loadConfig(dir);
  const { raw } = await readConfigDir(dir);
  await mkdir(dirname(OUT), { recursive: true });
  await writeFile(
    OUT,
    `// Generated by scripts/bundle-config.js from ${'config/'}. Do not edit.\nexport default ${JSON.stringify(raw, null, 2)};\n`,
  );
  console.log(`Bundled ${config.calculators.length} calculator(s): ${config.calculators.map((c) => c.id).join(', ') || '(none)'}`);
} catch (err) {
  console.error(err.message ?? err);
  process.exit(1);
}
